package com.workcompanion;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.event.*;
import java.awt.geom.*;
import java.awt.image.BufferedImage;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.prefs.Preferences;

/** A small, original cast of desktop friends. */
public final class WorkCompanion {
    private static final String[] NAMES = {"Mochi the Moth", "Puddle the Frog", "Sprout the Forestling", "Mallow the Ghost", "Toast the Bear", "Peach the Axolotl", "Boba the Cat", "Pebble the Turtle", "Sunny the Chick", "Pip the Fox"};
    private static final Color[] COLORS = {new Color(191,151,224),new Color(111,191,154),new Color(113,166,111),new Color(204,189,231),new Color(191,139,101),new Color(229,145,153),new Color(94,151,172),new Color(96,160,131),new Color(246,188,75),new Color(232,126,91)};
    private static final Color[] LIGHTS = {new Color(232,207,250),new Color(170,225,185),new Color(169,204,142),new Color(240,231,250),new Color(226,184,139),new Color(255,192,194),new Color(159,210,220),new Color(165,208,157),new Color(255,224,137),new Color(255,177,130)};
    private static final Color INK = new Color(54,49,64);
    private final Preferences prefs = Preferences.userNodeForPackage(WorkCompanion.class);
    private JFrame petFrame, settingsFrame; private Pet pet; private JWindow hover; private TrayIcon trayIcon; private int character, size; private boolean visible=true, dark;
    private Timer animation, hideTimer; private Point dragOffset; private boolean hoverDark;

    public static void main(String[] args) { SwingUtilities.invokeLater(() -> new WorkCompanion().start()); }

    private void start() {
        character=prefs.getInt("character",0); size=prefs.getInt("size",112); dark=detectDarkTheme();
        pet=new Pet(); petFrame=new JFrame(); petFrame.setUndecorated(true); petFrame.setAlwaysOnTop(true); petFrame.setType(Window.Type.UTILITY); petFrame.setBackground(new Color(0,0,0,0)); petFrame.setContentPane(pet); petFrame.setSize(size,size+12);
        Dimension screen=Toolkit.getDefaultToolkit().getScreenSize(); int x=prefs.getInt("x",screen.width-size-38), y=prefs.getInt("y",screen.height-size-100); petFrame.setLocation(Math.max(0,Math.min(x,screen.width-size)),Math.max(0,Math.min(y,screen.height-size)));
        pet.addMouseListener(new MouseAdapter(){ public void mouseEntered(MouseEvent e){showHover();} public void mouseExited(MouseEvent e){hideHoverLater();} public void mousePressed(MouseEvent e){dragOffset=e.getPoint();} public void mouseReleased(MouseEvent e){savePosition();} });
        pet.addMouseMotionListener(new MouseMotionAdapter(){ public void mouseDragged(MouseEvent e){Point p=petFrame.getLocation();petFrame.setLocation(p.x+e.getX()-dragOffset.x,p.y+e.getY()-dragOffset.y);if(hover!=null&&hover.isVisible())positionHover();} });
        petFrame.setVisible(true); animation=new Timer(40,e->{pet.tick++;pet.repaint();}); animation.start(); installTrayIcon();
    }

    private boolean detectDarkTheme(){try{Process p=new ProcessBuilder("reg.exe","query","HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Themes\\Personalize","/v","AppsUseLightTheme").redirectErrorStream(true).start();String out;try(BufferedReader r=new BufferedReader(new InputStreamReader(p.getInputStream()))){out=r.lines().reduce("",(a,b)->a+b);}p.waitFor();return out.matches("(?s).*AppsUseLightTheme\\s+REG_DWORD\\s+0x0\\s*.*");}catch(Exception ignored){return false;}}
    private Color bg(){return dark?new Color(35,34,42):new Color(255,255,255);} private Color panel(){return dark?new Color(45,43,54):new Color(248,247,250);} private Color fg(){return dark?new Color(245,241,250):new Color(53,48,62);} private Color muted(){return dark?new Color(184,177,196):new Color(124,117,134);} private Color line(){return dark?new Color(75,71,87):new Color(229,225,235);}
    private void savePosition(){prefs.putInt("x",petFrame.getX());prefs.putInt("y",petFrame.getY());}

    private void installTrayIcon(){if(!SystemTray.isSupported())return;PopupMenu menu=new PopupMenu();MenuItem open=new MenuItem("Settings");open.addActionListener(e->SwingUtilities.invokeLater(this::showSettings));MenuItem toggle=new MenuItem("Hide companion");toggle.addActionListener(e->SwingUtilities.invokeLater(()->setVisible(!visible)));MenuItem quit=new MenuItem("Quit Work Companion");quit.addActionListener(e->{if(animation!=null)animation.stop();SystemTray.getSystemTray().remove(trayIcon);petFrame.dispose();System.exit(0);});menu.add(open);menu.add(toggle);menu.addSeparator();menu.add(quit);trayIcon=new TrayIcon(makeTrayImage());trayIcon.setImageAutoSize(true);trayIcon.setToolTip("Work Companion · "+NAMES[character]);trayIcon.setPopupMenu(menu);trayIcon.addActionListener(e->SwingUtilities.invokeLater(this::showSettings));try{SystemTray.getSystemTray().add(trayIcon);}catch(AWTException ex){System.err.println("Could not add notification area icon: "+ex.getMessage());}}
    private Image makeTrayImage(){BufferedImage im=new BufferedImage(32,32,BufferedImage.TYPE_INT_ARGB);Graphics2D g=im.createGraphics();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);g.scale(.28,.28);drawCharacter(g,character,0,false);g.dispose();return im;}
    private void setVisible(boolean show){visible=show;petFrame.setVisible(show);if(trayIcon!=null&&trayIcon.getPopupMenu()!=null)trayIcon.getPopupMenu().getItem(1).setLabel(show?"Hide companion":"Show companion");}

    private void showHover(){dark=detectDarkTheme();if(hover!=null&&hoverDark!=dark){hover.dispose();hover=null;}hoverDark=dark;if(hover==null){hover=new JWindow(petFrame);hover.setAlwaysOnTop(true);JPanel shell=new JPanel(new FlowLayout(FlowLayout.CENTER,0,0));shell.setOpaque(false);RoundPanel card=new RoundPanel(bg(),line(),18);card.setLayout(new FlowLayout(FlowLayout.CENTER,5,5));card.setBorder(new EmptyBorder(1,4,1,4));JButton button=roundButton("⚙  Settings",true);button.addActionListener(e->showSettings());card.add(button);shell.add(card);hover.setContentPane(shell);hover.pack();hover.addMouseListener(new MouseAdapter(){public void mouseEntered(MouseEvent e){if(hideTimer!=null)hideTimer.stop();}public void mouseExited(MouseEvent e){hideHoverLater();}});}positionHover();hover.setVisible(true);}
    private JButton roundButton(String text,boolean primary){return new RoundedButton(text,primary);}
    private void hideHoverLater(){if(hideTimer!=null)hideTimer.stop();hideTimer=new Timer(300,e->{if(hover!=null&&!hover.getBounds().contains(MouseInfo.getPointerInfo().getLocation()))hover.setVisible(false);});hideTimer.setRepeats(false);hideTimer.start();}
    private void positionHover(){if(hover==null)return;int w=hover.getWidth(),h=hover.getHeight(),x=petFrame.getX()+(petFrame.getWidth()-w)/2,y=petFrame.getY()+petFrame.getHeight()-5;Dimension screen=Toolkit.getDefaultToolkit().getScreenSize();if(y+h>screen.height)y=petFrame.getY()-h+5;hover.setLocation(Math.max(0,Math.min(x,screen.width-w)),Math.max(0,y));}

    private void showSettings(){if(hover!=null)hover.setVisible(false);if(settingsFrame!=null&&settingsFrame.isVisible()){settingsFrame.toFront();return;}dark=detectDarkTheme();settingsFrame=new JFrame("Work Companion Settings");settingsFrame.setUndecorated(true);settingsFrame.setType(Window.Type.UTILITY);settingsFrame.setAlwaysOnTop(true);settingsFrame.setBackground(new Color(0,0,0,0));settingsFrame.setSize(390,510);settingsFrame.setLocationRelativeTo(petFrame);
        RoundPanel root=new RoundPanel(bg(),line(),24);root.setLayout(new BorderLayout(0,0));root.setBorder(new EmptyBorder(19,20,16,20));
        JPanel heading=new JPanel(new BorderLayout());heading.setOpaque(false);JPanel titles=new JPanel();titles.setOpaque(false);titles.setLayout(new BoxLayout(titles,BoxLayout.Y_AXIS));JLabel title=new JLabel("Meet your companion");title.setFont(new Font("Segoe UI",Font.BOLD,19));title.setForeground(fg());JLabel sub=new JLabel("Pick a little friend for your desktop");sub.setFont(new Font("Segoe UI",Font.PLAIN,12));sub.setForeground(muted());titles.add(title);titles.add(Box.createVerticalStrut(3));titles.add(sub);JButton close=roundButton("×",false);close.setFont(new Font("Segoe UI",Font.PLAIN,20));close.addActionListener(e->settingsFrame.dispose());heading.add(titles,BorderLayout.WEST);heading.add(close,BorderLayout.EAST);root.add(heading,BorderLayout.NORTH);
        JPanel choices=new JPanel(new GridLayout(5,2,9,9));choices.setOpaque(false);choices.setBorder(new EmptyBorder(18,0,12,0));ButtonGroup group=new ButtonGroup();JToggleButton[] buttons=new JToggleButton[NAMES.length];for(int i=0;i<NAMES.length;i++){final int idx=i;CharacterCard card=new CharacterCard(idx);card.setSelected(i==character);card.addActionListener(e->{character=idx;for(int j=0;j<buttons.length;j++)if(buttons[j]!=null)buttons[j].setSelected(j==idx);pet.repaint();if(trayIcon!=null){trayIcon.setImage(makeTrayImage());trayIcon.setToolTip("Work Companion · "+NAMES[character]);}});buttons[i]=card;group.add(card);choices.add(card);}root.add(choices,BorderLayout.CENTER);
        JPanel bottom=new JPanel(new BorderLayout(0,5));bottom.setOpaque(false);JPanel sizeRow=new JPanel(new BorderLayout());sizeRow.setOpaque(false);JLabel sizeLabel=new JLabel("Character size");sizeLabel.setFont(new Font("Segoe UI",Font.BOLD,12));sizeLabel.setForeground(fg());JLabel pixels=new JLabel(size+" px");pixels.setFont(new Font("Segoe UI",Font.PLAIN,12));pixels.setForeground(muted());sizeRow.add(sizeLabel,BorderLayout.WEST);sizeRow.add(pixels,BorderLayout.EAST);JSlider slider=new JSlider(80,160,size);slider.setOpaque(false);slider.setForeground(fg());slider.addChangeListener(e->pixels.setText(slider.getValue()+" px"));JPanel actions=new JPanel(new FlowLayout(FlowLayout.RIGHT,0,4));actions.setOpaque(false);JButton done=roundButton("Done",true);done.setFont(new Font("Segoe UI",Font.BOLD,12));done.setBorder(new EmptyBorder(8,20,8,20));done.addActionListener(e->{size=slider.getValue();prefs.putInt("character",character);prefs.putInt("size",size);petFrame.setSize(size,size+12);pet.revalidate();pet.repaint();savePosition();settingsFrame.dispose();});actions.add(done);bottom.add(sizeRow,BorderLayout.NORTH);bottom.add(slider,BorderLayout.CENTER);bottom.add(actions,BorderLayout.SOUTH);root.add(bottom,BorderLayout.SOUTH);
        settingsFrame.setContentPane(root);settingsFrame.addWindowListener(new WindowAdapter(){public void windowClosed(WindowEvent e){pet.repaint();}});settingsFrame.setVisible(true);
    }

    private final class RoundedButton extends JButton {final boolean primary;RoundedButton(String text,boolean primary){super(text);this.primary=primary;setFont(new Font("Segoe UI",Font.PLAIN,12));setForeground(primary?(dark?new Color(245,233,255):new Color(76,53,103)):fg());setFocusPainted(false);setBorderPainted(false);setContentAreaFilled(false);setOpaque(false);setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));setBorder(new EmptyBorder(7,11,7,11));}protected void paintComponent(Graphics raw){Graphics2D g=(Graphics2D)raw.create();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);Color c=primary?(dark?new Color(77,63,93):new Color(241,232,250)):(dark?new Color(58,55,68):new Color(245,243,248));if(getModel().isPressed())c=c.darker();else if(getModel().isRollover())c=c.brighter();g.setColor(c);g.fill(new RoundRectangle2D.Double(0,0,getWidth(),getHeight(),16,16));g.dispose();super.paintComponent(raw);}}
    private final class CharacterCard extends JToggleButton {private final int id;CharacterCard(int id){this.id=id;setOpaque(false);setContentAreaFilled(false);setFocusPainted(false);setBorderPainted(false);setPreferredSize(new Dimension(165,58));setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));}protected void paintComponent(Graphics raw){Graphics2D g=(Graphics2D)raw.create();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);boolean selected=isSelected();RoundPanel.fill(g,0,0,getWidth(),getHeight(),15,selected?(dark?new Color(70,59,83):new Color(244,235,251)):panel());g.setColor(selected?(dark?new Color(157,125,188):new Color(179,145,207)):line());g.setStroke(new BasicStroke(selected?1.7f:1));g.draw(new RoundRectangle2D.Double(.7,.7,getWidth()-1.4,getHeight()-1.4,15,15));Graphics2D icon=(Graphics2D)g.create();icon.translate(4,3);icon.scale(.45,.45);drawCharacter(icon,id,0,false);icon.dispose();g.setColor(fg());g.setFont(new Font("Segoe UI",Font.PLAIN,11));g.drawString(NAMES[id].replaceFirst(" the.*$",""),59,34);if(selected){g.setColor(dark?new Color(220,192,244):new Color(129,91,157));g.fill(new Ellipse2D.Double(getWidth()-22,21,8,8));}g.dispose();}}

    private static final class RoundPanel extends JPanel {final Color fill,stroke;final int radius;RoundPanel(Color fill,Color stroke,int radius){this.fill=fill;this.stroke=stroke;this.radius=radius;setOpaque(false);}static void fill(Graphics2D g,int x,int y,int w,int h,int r,Color c){g.setColor(c);g.fill(new RoundRectangle2D.Double(x,y,w,h,r,r));}protected void paintComponent(Graphics raw){Graphics2D g=(Graphics2D)raw.create();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);fill(g,0,0,getWidth()-1,getHeight()-1,radius,fill);g.setColor(stroke);g.draw(new RoundRectangle2D.Double(.5,.5,getWidth()-2,getHeight()-2,radius,radius));g.dispose();super.paintComponent(raw);}}

    private final class Pet extends JPanel {long tick;Pet(){setOpaque(false);}protected void paintComponent(Graphics raw){super.paintComponent(raw);Graphics2D g=(Graphics2D)raw.create();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);double s=Math.min(getWidth(),getHeight()-8)/112.0;g.translate((getWidth()-112*s)/2,4+Math.sin(tick*.065)*2);g.scale(s,s);drawCharacter(g,character,tick,tick%145>137);g.dispose();}}

    /** Each design gets a distinct silhouette, face, limbs, and costume detail. */
    private void drawCharacter(Graphics2D raw,int id,long tick,boolean blink){Graphics2D g=(Graphics2D)raw.create();g.setColor(new Color(39,32,49,34));g.fill(new Ellipse2D.Double(17,98,78,9));Color base=COLORS[id],light=LIGHTS[id];g.setStroke(new BasicStroke(2.5f,BasicStroke.CAP_ROUND,BasicStroke.JOIN_ROUND));
        // Little feet and arms animate with the idle sway.
        double sway=Math.sin(tick*.055)*2;g.setColor(base.darker());g.fill(new Ellipse2D.Double(31,87+sway,17,12));g.fill(new Ellipse2D.Double(64,87-sway,17,12));g.setStroke(new BasicStroke(5,BasicStroke.CAP_ROUND,BasicStroke.JOIN_ROUND));g.draw(new Line2D.Double(23,65,15,75+sway));g.draw(new Line2D.Double(89,65,97,75-sway));
        // Distinct silhouettes and accessories for each friend.
        switch(id){
            case 0->{g.setColor(base.darker());g.fill(new Ellipse2D.Double(6,26,28,33));g.fill(new Ellipse2D.Double(78,26,28,33));g.setColor(light);g.fill(new Ellipse2D.Double(9,31,21,25));g.fill(new Ellipse2D.Double(82,31,21,25));g.setColor(base);g.fill(new Ellipse2D.Double(25,28,62,65));g.setColor(new Color(249,232,255));g.fill(new Ellipse2D.Double(28,28,16,17));g.fill(new Ellipse2D.Double(68,28,16,17));g.setColor(new Color(219,186,242));g.fill(new Ellipse2D.Double(49,54,15,22));g.setColor(new Color(249,228,255));g.fill(new Ellipse2D.Double(49,80,15,7));}
            case 1->{g.setColor(base);g.fill(new Ellipse2D.Double(18,34,76,59));g.fill(new Ellipse2D.Double(21,24,25,28));g.fill(new Ellipse2D.Double(66,24,25,28));g.setColor(light);g.fill(new Ellipse2D.Double(27,54,57,35));g.setColor(new Color(255,238,156));g.fill(new Ellipse2D.Double(44,38,23,12));g.fill(new Ellipse2D.Double(50,38,12,19));}
            case 2->{g.setColor(base);Path2D body=new Path2D.Double();body.moveTo(22,83);body.curveTo(16,53,26,32,43,31);body.curveTo(51,12,67,16,68,31);body.curveTo(94,29,99,59,88,83);body.closePath();g.fill(body);g.setColor(light);g.fill(new Ellipse2D.Double(37,59,41,29));g.setColor(new Color(83,131,79));g.fill(new Ellipse2D.Double(38,24,22,9));g.fill(new Ellipse2D.Double(57,19,17,8));g.setColor(new Color(244,205,102));g.fill(new Ellipse2D.Double(51,35,11,11));}
            case 3->{g.setColor(new Color(base.getRed(),base.getGreen(),base.getBlue(),238));g.fill(new RoundRectangle2D.Double(20,23,72,68,32,32));g.fill(new Ellipse2D.Double(30,16,19,21));g.fill(new Ellipse2D.Double(64,16,19,21));g.setColor(light);g.fill(new Ellipse2D.Double(31,55,49,30));g.setColor(new Color(255,255,255,175));g.fill(new Ellipse2D.Double(39,33,8,13));g.fill(new Ellipse2D.Double(68,29,6,10));}
            case 4->{g.setColor(base);g.fillRoundRect(21,29,70,64,27,27);g.fillRoundRect(20,19,25,28,12,12);g.fillRoundRect(67,19,25,28,12,12);g.setColor(new Color(240,212,181));g.fill(new Ellipse2D.Double(30,56,51,31));g.setColor(new Color(116,77,56));g.fill(new Ellipse2D.Double(50,61,13,10));g.setColor(new Color(255,221,113));g.fill(new Arc2D.Double(40,38,32,19,0,180,Arc2D.PIE));}
            case 5->{g.setColor(base);g.fill(new Ellipse2D.Double(17,36,78,55));g.fill(new Ellipse2D.Double(25,25,29,26));g.fill(new Ellipse2D.Double(61,25,29,26));g.setColor(light);g.fill(new Ellipse2D.Double(30,55,54,31));g.setColor(new Color(247,155,168));g.fill(new Ellipse2D.Double(12,56,14,23));g.fill(new Ellipse2D.Double(86,56,14,23));g.setColor(new Color(255,219,206));g.fill(new Ellipse2D.Double(40,75,30,11));}
            case 6->{g.setColor(base);Path2D cat=new Path2D.Double();cat.moveTo(20,42);cat.lineTo(26,17);cat.lineTo(46,32);cat.curveTo(56,26,67,29,75,34);cat.lineTo(91,17);cat.lineTo(94,48);cat.curveTo(104,76,87,94,57,94);cat.curveTo(28,94,13,72,20,42);g.fill(cat);g.setColor(light);g.fill(new Ellipse2D.Double(30,55,55,33));g.setColor(new Color(250,230,173));g.fill(new Ellipse2D.Double(40,42,8,11));g.fill(new Ellipse2D.Double(67,42,8,11));g.setColor(new Color(231,163,178));g.fill(new Polygon(new int[]{53,61,57},new int[]{58,58,62},3));g.setColor(new Color(240,201,114));g.fill(new Ellipse2D.Double(47,23,19,12));}
            case 7->{g.setColor(base);g.fill(new Ellipse2D.Double(14,34,84,59));g.setColor(new Color(122,184,139));g.fill(new Ellipse2D.Double(26,27,61,51));g.setColor(new Color(93,143,118));g.setStroke(new BasicStroke(3));g.drawArc(33,34,47,37,0,180);g.setColor(light);g.fill(new Ellipse2D.Double(75,46,29,31));g.setColor(new Color(244,224,188));g.fill(new Ellipse2D.Double(82,57,5,5));g.fill(new Ellipse2D.Double(94,57,5,5));g.setColor(new Color(244,194,123));g.fill(new Ellipse2D.Double(47,49,10,10));}
            case 8->{g.setColor(base);g.fill(new Ellipse2D.Double(22,32,68,62));g.fill(new Ellipse2D.Double(25,19,25,29));g.fill(new Ellipse2D.Double(62,19,25,29));g.setColor(new Color(255,225,139));g.fill(new Ellipse2D.Double(35,50,43,37));g.setColor(new Color(255,255,247));g.fill(new Ellipse2D.Double(37,39,14,18));g.fill(new Ellipse2D.Double(64,39,14,18));g.setColor(INK);g.fill(new Ellipse2D.Double(43,46,5,7));g.fill(new Ellipse2D.Double(69,46,5,7));g.setColor(new Color(244,148,92));g.fill(new Polygon(new int[]{52,66,59},new int[]{57,57,66},3));g.setColor(new Color(241,155,104));g.fill(new Ellipse2D.Double(47,73,13,12));}
            default->{g.setColor(base);Path2D fox=new Path2D.Double();fox.moveTo(20,43);fox.lineTo(25,14);fox.lineTo(48,31);fox.curveTo(60,26,72,28,79,34);fox.lineTo(92,16);fox.lineTo(96,51);fox.curveTo(100,82,80,95,57,95);fox.curveTo(30,95,13,74,20,43);g.fill(fox);g.setColor(new Color(255,232,201));g.fill(new Ellipse2D.Double(29,55,57,35));g.setColor(new Color(253,242,222));g.fill(new Polygon(new int[]{27,31,43},new int[]{20,38,31},3));g.fill(new Polygon(new int[]{88,81,75},new int[]{22,38,32},3));g.setColor(INK);g.setColor(new Color(80,55,57));g.fill(new Ellipse2D.Double(52,58,10,7));g.setColor(new Color(255,213,132));g.fill(new Ellipse2D.Double(48,23,18,11));}
        }
        // Soft outline-like features and eye sparkle keep the faces readable at small sizes.
        g.setColor(INK);g.setStroke(new BasicStroke(2.2f,BasicStroke.CAP_ROUND,BasicStroke.JOIN_ROUND));float eyeH=blink?1:5;double eyeY=(id==1?28:(id==4?38:(id==6||id==9?43:(id==8?46:51))));double leftEye=id==1?35:(id==7?83:39),rightEye=id==1?73:(id==7?95:68);g.fill(new Ellipse2D.Double(leftEye,eyeY,5,eyeH));g.fill(new Ellipse2D.Double(rightEye,eyeY,5,eyeH));if(!blink){g.setColor(Color.WHITE);g.fill(new Ellipse2D.Double(leftEye+1,eyeY,1.8,2));g.fill(new Ellipse2D.Double(rightEye+1,eyeY,1.8,2));}g.setColor(new Color(246,153,163,190));g.fill(new Ellipse2D.Double(28,59,10,5));g.fill(new Ellipse2D.Double(75,59,10,5));g.setColor(INK);g.draw(new Arc2D.Double(51,58,10,8,205,130,Arc2D.OPEN));g.dispose();
    }
}
